// Ne Giysem? watch face for Wear OS 5+ (Galaxy Watch 7 and newer): Watch Face Format, resources only, no code.
// The XML and texts are generated by tools/build_face.py; the stickers by tools/stickers.py.
plugins {
    id("com.android.application")
}

// Same upload key as the phone app, only from the environment (GitHub secrets in the cloud build, see RELEASE.md).
val releaseKeyFile = System.getenv("NG_KEYSTORE_FILE")?.takeIf { it.isNotBlank() }?.let { file(it) }

android {
    namespace = "com.negiysem.app.watchface"
    compileSdk = 36

    defaultConfig {
        // A watch face is its own Play listing: Play does not accept it in the same bundle as app code.
        applicationId = "com.negiysem.app.watchface"
        // Weather needs Watch Face Format version 2, which starts with Wear OS 5 (API 34).
        minSdk = 34
        targetSdk = 36
        versionCode = System.getenv("GITHUB_RUN_NUMBER")?.toIntOrNull() ?: 1
        versionName = "1.0"
    }

    signingConfigs {
        // The phone app's fixed debug key, so a newer debug build installs over the previous one.
        getByName("debug") {
            storeFile = rootProject.file("app/debug.keystore")
            storePassword = "android"
            keyAlias = "androiddebugkey"
            keyPassword = "android"
        }
        create("release") {
            if (releaseKeyFile != null) {
                storeFile = releaseKeyFile
                storePassword = System.getenv("NG_KEYSTORE_PASSWORD")
                keyAlias = System.getenv("NG_KEY_ALIAS")?.takeIf { it.isNotBlank() } ?: "negiysem-upload"
                keyPassword = System.getenv("NG_KEY_PASSWORD")?.takeIf { it.isNotEmpty() } ?: System.getenv("NG_KEYSTORE_PASSWORD")
            }
        }
    }

    buildTypes {
        debug {
            isMinifyEnabled = true
        }
        release {
            isMinifyEnabled = true
            // Resource shrinking would drop the stickers: only watchface.xml refers to them, by name.
            isShrinkResources = false
            signingConfig = if (releaseKeyFile != null) signingConfigs.getByName("release") else null
        }
    }
}
